insert into erp_supply.freight_route_reference(
  organization_id,model_version,origin_city,carrier,destination_city,destination_department,
  sample_count,weight_sample_count,weight_p20,weight_p50,weight_p80,
  cost_p20,cost_p50,cost_p80,
  transit_sample_count,transit_p50_days,transit_p80_days,
  novelty_sample_count,novelty_rate,on_time_sample_count,on_time_rate,
  charge_real_sample_count,charge_to_real_p50,dimensional_uplift_rate,
  source_start,source_end
)
select
  o.id,'11.40.0','TULUA',
  erp_supply.freight_norm_v1140(s.carrier),
  erp_supply.freight_norm_v1140(s.destination_city),
  erp_supply.freight_norm_v1140(s.destination_department),
  s.sample_count,s.weight_sample_count,s.weight_p20,s.weight_p50,s.weight_p80,
  s.cost_p20,s.cost_p50,s.cost_p80,
  s.transit_sample_count,s.transit_p50_days,s.transit_p80_days,
  s.novelty_sample_count,s.novelty_rate,s.on_time_sample_count,s.on_time_rate,
  s.charge_real_sample_count,s.charge_to_real_p50,s.dimensional_uplift_rate,
  s.source_start::date,s.source_end::date
from seed s
cross join erp_supply.organizations o
where o.code='EI'
on conflict(organization_id,model_version,origin_city,carrier,destination_city,destination_department)
do update set
  sample_count=excluded.sample_count,weight_sample_count=excluded.weight_sample_count,
  weight_p20=excluded.weight_p20,weight_p50=excluded.weight_p50,weight_p80=excluded.weight_p80,
  cost_p20=excluded.cost_p20,cost_p50=excluded.cost_p50,cost_p80=excluded.cost_p80,
  transit_sample_count=excluded.transit_sample_count,transit_p50_days=excluded.transit_p50_days,
  transit_p80_days=excluded.transit_p80_days,novelty_sample_count=excluded.novelty_sample_count,
  novelty_rate=excluded.novelty_rate,on_time_sample_count=excluded.on_time_sample_count,
  on_time_rate=excluded.on_time_rate,charge_real_sample_count=excluded.charge_real_sample_count,
  charge_to_real_p50=excluded.charge_to_real_p50,dimensional_uplift_rate=excluded.dimensional_uplift_rate,
  source_start=excluded.source_start,source_end=excluded.source_end;

create or replace function erp_supply.freight_model_predict_v1140(
  p_org uuid,
  p_carrier text,
  p_department text,
  p_city text,
  p_weight_kg numeric default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_carrier text:=erp_supply.freight_norm_v1140(p_carrier);
  v_city text:=erp_supply.freight_norm_v1140(p_city);
  v_department text:=erp_supply.freight_norm_v1140(p_department);
  v_weight numeric:=case when p_weight_kg is null then null else greatest(p_weight_kg,0) end;
  v_band integer:=erp_supply.freight_weight_band_v1140(p_weight_kg);
  v_lw numeric:=ln(1+coalesce(v_weight,0));
  v_model erp_supply.freight_prediction_models%rowtype;
  v_ref erp_supply.freight_route_reference%rowtype;
  v_log numeric;
  v_mid numeric;
  v_low numeric;
  v_high numeric;
  v_low90 numeric;
  v_high90 numeric;
  v_p20 numeric;
  v_p80 numeric;
  v_p10 numeric;
  v_p90 numeric;
  v_confidence text;
  v_uncertainty numeric;
begin
  select * into v_model
  from erp_supply.freight_prediction_models m
  where m.organization_id=p_org
    and m.model_code='EI_FREIGHT_RIDGE_WEIGHT'
    and m.active
  order by m.source_end desc,m.created_at desc
  limit 1;

  if not found then
    return jsonb_build_object('available',false,'reason','MODEL_NOT_AVAILABLE','carrier',v_carrier,'version','11.40.0');
  end if;

  select * into v_ref
  from erp_supply.freight_route_reference r
  where r.organization_id=p_org
    and r.model_version=v_model.model_version
    and r.origin_city=v_model.origin_city
    and r.carrier=v_carrier
    and r.destination_city=v_city
    and (r.destination_department=v_department or v_department='')
  order by (r.destination_department=v_department) desc,r.sample_count desc
  limit 1;

  if v_weight is null or v_weight<=0 then
    if v_ref.id is null or v_ref.cost_p50 is null then
      return jsonb_build_object(
        'available',false,'reason','WEIGHT_REQUIRED_FOR_UNSEEN_ROUTE',
        'carrier',v_carrier,'city',p_city,'department',p_department,
        'routeSamples',coalesce(v_ref.sample_count,0),'version',v_model.model_version
      );
    end if;
    v_mid:=v_ref.cost_p50;
    v_low:=coalesce(v_ref.cost_p20,v_mid);
    v_high:=coalesce(v_ref.cost_p80,v_mid);
    v_low90:=v_low;
    v_high90:=v_high;
  else
    v_log:=v_model.intercept
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>('carrier='||v_carrier)),0)
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>('dest='||v_city)),0)
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>('dept='||v_department)),0)
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>('band='||v_band::text)),0)
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>'lw'),0)*v_lw
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>'lw2'),0)*v_lw*v_lw
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>(v_carrier||':lw')),0)*v_lw
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>(v_carrier||':lw2')),0)*v_lw*v_lw
      +coalesce(erp_supply.safe_numeric(v_model.coefficients->>('destlw='||v_city)),0)*v_lw;

    v_mid:=greatest(0,exp(v_log)-1);
    v_p20:=coalesce(erp_supply.safe_numeric(v_model.calibration#>>array[v_carrier,'p20']),0.80);
    v_p80:=coalesce(erp_supply.safe_numeric(v_model.calibration#>>array[v_carrier,'p80']),1.25);
    v_p10:=coalesce(erp_supply.safe_numeric(v_model.calibration#>>array[v_carrier,'p10']),0.70);
    v_p90:=coalesce(erp_supply.safe_numeric(v_model.calibration#>>array[v_carrier,'p90']),1.50);
    v_low:=v_mid*v_p20;
    v_high:=v_mid*v_p80;
    v_low90:=v_mid*v_p10;
    v_high90:=v_mid*v_p90;
  end if;

  v_uncertainty:=case when v_mid>0 then greatest(0,(v_high-v_low)/(2*v_mid)*100) else null end;
  v_confidence:=case
    when v_weight is null then
      case when coalesce(v_ref.sample_count,0)>=10 then 'MEDIUM'
           when coalesce(v_ref.sample_count,0)>=3 then 'LOW'
           else 'LEARNING' end
    when coalesce(v_ref.sample_count,0)>=10 then 'HIGH'
    when coalesce(v_ref.sample_count,0)>=3 then 'MEDIUM'
    else 'LOW'
  end;

  return jsonb_build_object(
    'available',true,
    'carrier',v_carrier,
    'city',p_city,
    'department',p_department,
    'originCity',v_model.origin_city,
    'weightKg',v_weight,
    'basis',case when v_weight is null then 'ROUTE_HISTORY' else 'WEIGHT_MODEL' end,
    'estimateLow',round(v_low,0),
    'estimateMid',round(v_mid,0),
    'estimateHigh',round(v_high,0),
    'conservativeLow',round(v_low90,0),
    'conservativeHigh',round(v_high90,0),
    'uncertaintyPct',case when v_uncertainty is null then null else round(v_uncertainty,1) end,
    'confidence',v_confidence,
    'routeSamples',coalesce(v_ref.sample_count,0),
    'sourcePeriod',jsonb_build_object('from',v_model.source_start,'to',v_model.source_end),
    'transit',jsonb_build_object(
      'samples',coalesce(v_ref.transit_sample_count,0),
      'medianDays',v_ref.transit_p50_days,
      'p80Days',v_ref.transit_p80_days
    ),
    'risk',jsonb_build_object(
      'noveltySamples',coalesce(v_ref.novelty_sample_count,0),
      'noveltyRate',v_ref.novelty_rate,
      'onTimeSamples',coalesce(v_ref.on_time_sample_count,0),
      'onTimeRate',v_ref.on_time_rate,
      'chargeRealSamples',coalesce(v_ref.charge_real_sample_count,0),
      'chargeToRealP50',v_ref.charge_to_real_p50,
      'dimensionalUpliftRate',v_ref.dimensional_uplift_rate
    ),
    'modelMetrics',v_model.metrics,
    'modelVersion',v_model.model_version
  );
end;
$$;
revoke all on function erp_supply.freight_model_predict_v1140(uuid,text,text,text,numeric) from public,anon,authenticated;

create or replace function public.erp_x_freight_predictions(
  p_department text default null,
  p_city text default null,
  p_weight_kg numeric default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_rows jsonb;
  v_cheapest text;
  v_fastest text;
  v_stable text;
  v_model erp_supply.freight_prediction_models%rowtype;
begin
  perform erp_supply.require_profile();
  if nullif(trim(coalesce(p_city,'')),'') is null then
    return jsonb_build_object('available',false,'reason','CITY_REQUIRED','version','11.40.0');
  end if;

  select * into v_model
  from erp_supply.freight_prediction_models m
  where m.organization_id=v_org and m.model_code='EI_FREIGHT_RIDGE_WEIGHT' and m.active
  order by m.source_end desc,m.created_at desc limit 1;
  if not found then return jsonb_build_object('available',false,'reason','MODEL_NOT_AVAILABLE','version','11.40.0'); end if;

  with carriers(carrier) as(values('COLVANES'),('TCC'),('VELOENVIOS')),
  pred as(
    select carrier,erp_supply.freight_model_predict_v1140(v_org,carrier,p_department,p_city,p_weight_kg) prediction
    from carriers
  ),
  available as(
    select carrier,prediction
    from pred
    where coalesce((prediction->>'available')::boolean,false)
  )
  select coalesce(jsonb_agg(prediction order by coalesce(erp_supply.safe_numeric(prediction->>'estimateMid'),1e18)),'[]'::jsonb)
  into v_rows
  from available;

  with carriers(carrier) as(values('COLVANES'),('TCC'),('VELOENVIOS')),
  pred as(
    select carrier,erp_supply.freight_model_predict_v1140(v_org,carrier,p_department,p_city,p_weight_kg) prediction
    from carriers
  ),
  available as(
    select carrier,prediction
    from pred
    where coalesce((prediction->>'available')::boolean,false)
  )
  select carrier into v_cheapest
  from available
  order by erp_supply.safe_numeric(prediction->>'estimateMid') nulls last
  limit 1;

  with carriers(carrier) as(values('COLVANES'),('TCC'),('VELOENVIOS')),
  pred as(
    select carrier,erp_supply.freight_model_predict_v1140(v_org,carrier,p_department,p_city,p_weight_kg) prediction
    from carriers
  ),
  available as(
    select carrier,prediction
    from pred
    where coalesce((prediction->>'available')::boolean,false)
  )
  select carrier into v_fastest
  from available
  where erp_supply.safe_numeric(prediction#>>'{transit,medianDays}') is not null
  order by erp_supply.safe_numeric(prediction#>>'{transit,medianDays}') asc
  limit 1;

  with carriers(carrier) as(values('COLVANES'),('TCC'),('VELOENVIOS')),
  pred as(
    select carrier,erp_supply.freight_model_predict_v1140(v_org,carrier,p_department,p_city,p_weight_kg) prediction
    from carriers
  ),
  available as(
    select carrier,prediction
    from pred
    where coalesce((prediction->>'available')::boolean,false)
  )
  select carrier into v_stable
  from available
  where erp_supply.safe_numeric(prediction->>'uncertaintyPct') is not null
  order by erp_supply.safe_numeric(prediction->>'uncertaintyPct') asc
  limit 1;

  return jsonb_build_object(
    'available',jsonb_array_length(v_rows)>0,
    'city',p_city,
    'department',p_department,
    'weightKg',p_weight_kg,
    'mode',case when coalesce(p_weight_kg,0)>0 then 'REFINED_WEIGHT_MODEL' else 'PRELIMINARY_ROUTE_HISTORY' end,
    'carriers',v_rows,
    'cheapestCarrier',v_cheapest,
    'fastestCarrier',v_fastest,
    'mostStableCarrier',v_stable,
    'training',jsonb_build_object(
      'samples',v_model.sample_count,
      'sourceFrom',v_model.source_start,
      'sourceTo',v_model.source_end,
      'metrics',v_model.metrics,
      'privacy','AGGREGATED_NO_PII'
    ),
    'version',v_model.model_version
  );
end;
$$;

revoke all on function public.erp_x_freight_predictions(text,text,numeric) from public,anon;
grant execute on function public.erp_x_freight_predictions(text,text,numeric) to authenticated;

comment on table erp_supply.freight_prediction_models
is 'Modelos de flete derivados de datos agregados; nunca almacena PII de destinatarios.';
comment on table erp_supply.freight_route_reference
is 'Estadística agregada por transportadora/destino para costo, tránsito y riesgo; sin datos personales.';
comment on function public.erp_x_freight_predictions(text,text,numeric)
is 'V11.40.0: predicción comparativa COLVANES/TCC/VELOENVIOS; preliminar por ruta o refinada por peso.';

notify pgrst,'reload schema';
commit;
